import{_ as a,o as e,c as o,a2 as r}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"钉钉","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/channels/dingtalk.md","filePath":"zh/integrations/channels/dingtalk.md","lastUpdated":1790952322000}'),l={name:"zh/integrations/channels/dingtalk.md"};function n(i,t,s,h,d,c){return e(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="钉钉" tabindex="-1">钉钉 <a class="header-anchor" href="#钉钉" aria-label="Permalink to &quot;钉钉&quot;">​</a></h1><p>把 Memoh Bot 接入钉钉,支持企业内私聊与群聊:入站消息经由钉钉 Stream 模式送达,回复与媒体走钉钉官方 API。</p><div class="warning custom-block"><p class="custom-block-title">使用限制</p><ul><li>回复按完整消息送达,不做逐 token 流式输出。</li></ul></div><h2 id="前提条件" tabindex="-1">前提条件 <a class="header-anchor" href="#前提条件" aria-label="Permalink to &quot;前提条件&quot;">​</a></h2><ul><li>能进入组织对应的钉钉开放平台,并有创建应用的权限。</li><li>不需要公网回调地址:Memoh 自动维护与钉钉的 Stream 长连接来接收消息。</li></ul><h2 id="步骤" tabindex="-1">步骤 <a class="header-anchor" href="#步骤" aria-label="Permalink to &quot;步骤&quot;">​</a></h2><h3 id="_1-在钉钉开放平台创建应用" tabindex="-1">1. 在钉钉开放平台创建应用 <a class="header-anchor" href="#_1-在钉钉开放平台创建应用" aria-label="Permalink to &quot;1. 在钉钉开放平台创建应用&quot;">​</a></h3><p>在组织对应的钉钉开放平台:</p><ol><li>创建或选用一个应用作为 Bot。</li><li>为该应用开启 Bot/消息能力。</li><li>复制 <strong>App Key</strong> 和 <strong>App Secret</strong>。</li><li>为应用授予消息权限,并在组织内发布,让使用者能够访问。</li></ol><h3 id="_2-在-memoh-里添加渠道" tabindex="-1">2. 在 Memoh 里添加渠道 <a class="header-anchor" href="#_2-在-memoh-里添加渠道" aria-label="Permalink to &quot;2. 在 Memoh 里添加渠道&quot;">​</a></h3><p>在 Memoh:</p><ol><li>打开 Bot 的 <strong>平台</strong> 标签页。</li><li>点 <strong>Add Channel</strong>,选择 <strong>DingTalk</strong>。</li><li>填入 <strong>App Key</strong> 和 <strong>App Secret</strong>。</li><li>点 <strong>Save and Enable</strong>。</li></ol><p>Memoh 会自动维护钉钉 Stream 长连接,不需要粘贴 webhook 回调地址。</p><h2 id="凭据" tabindex="-1">凭据 <a class="header-anchor" href="#凭据" aria-label="Permalink to &quot;凭据&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><strong>App Key</strong></td><td>是</td><td>钉钉应用的 Key,在钉钉开放平台的应用凭据处复制。</td></tr><tr><td><strong>App Secret</strong></td><td>是</td><td>钉钉应用的 Secret,与 App Key 在同一处复制。</td></tr></tbody></table><h2 id="验证" tabindex="-1">验证 <a class="header-anchor" href="#验证" aria-label="Permalink to &quot;验证&quot;">​</a></h2><p>私聊给 Bot 发送 <code>/help</code>,或在群聊中 @Bot 并发送 <code>/help</code>。Bot 回复命令列表,说明渠道已接通。</p><h2 id="群聊" tabindex="-1">群聊 <a class="header-anchor" href="#群聊" aria-label="Permalink to &quot;群聊&quot;">​</a></h2><p>Bot 支持钉钉群聊:在支持的群里 @Bot 即可触发回复。</p><h2 id="停用与更换凭据" tabindex="-1">停用与更换凭据 <a class="header-anchor" href="#停用与更换凭据" aria-label="Permalink to &quot;停用与更换凭据&quot;">​</a></h2><p>随时可在 Bot 的 <strong>平台</strong> 标签页停用或移除该渠道。更换凭据时,在同一面板更新 <strong>App Key</strong> / <strong>App Secret</strong> 并保存即可。</p>',21)])])}const m=a(l,[["render",n]]);export{g as __pageData,m as default};
